/* one of each: a subject (the same animal, fossil or place) appears once in a tour, never twice, and a stop's own card photo
   is not repeated as a pin. Later stops keep their subjects; the first stop shows only what no other stop shows.
   cap: photos per stop, first: photos on the first stop. */
window.gfOneOfEach=function(steps,PIN,CARD,cap,first){try{
 const KEYS=[["galápagos tortoise","giant tortoise","galapagos giant tortoise","chelonoidis"],["aldabra"],["iguana"],["komodo"],["kiwi"],["dodo"],["coconut crab","robber crab"],["red crab","crabs on","crab migration","40 million","eggs in the sea","babies come"],["dwarf elephant","sicily"],["mammoth"],["tree lobster","stick insect"],["ball’s pyramid","ball's pyramid","balls pyramid"],["darwin’s finches by","darwin's finches"],["kākāpō","kakapo"],["moa"],["takah"],["kea"],["tuatara"],["penguin"],["booby"],["cormorant"],["sea lion"],["monk seal"],["baikal seal","nerpa","ushkan"],["wētā","weta"],["giant rat","papagomys"],["sloth"],["island fox"],["key deer"],["dragon"+"’s blood","dragon's blood","dragonblood"],["roraima","kukenán","kukenan"],["krakatau","krakatoa","rakata"],["cichlid","mbuna"],["nile perch"],["tree snake"],["lucy"],["neanderthal"],["turkana","erectus","peking"],["floresiensis","hobbit"],["naledi"],["denisova"],["harbin","longi"],["orangutan"],["gorilla"],["chimp"],["bonobo"],["ring-tailed"],["laetoli"],["olduvai"],["lake mungo"],["jebel irhoud"],["iʻiwi","iiwi","i'iwi","drepanis","hawaiian honeycreeper"],["apapane","ʻapapane"],["palila"],["akiapol","ʻakiapō"],["silversword"],["nēnē","nene"],["hoary bat"]];
 const fold=s=>String(s||"").toLowerCase();const key=q=>{const f=PIN[q.label]||"",t=fold(q.label)+" "+fold(f);for(const k of KEYS)if(k.some(w=>t.includes(w)))return k[0];return "f:"+(f||q.label)};
 const cardKey=St=>{const f=CARD[St.title];return f?key({label:"",_f:f})+"|"+f:null};
 const first0=steps[0],later=steps.filter(S=>S!==first0&&S.phPins);
 /* each later stop: one of each subject, never its own card photo, no subject shared with an earlier stop */
 const owner=new Map;later.forEach(St=>{const cf=CARD[St.title],out=[];St.phPins.forEach(q=>{const k=key(q);if((cf&&PIN[q.label]===cf)||owner.has(k))return;owner.set(k,St);out.push(q)});St.phPins=out});
 /* the first stop keeps its own photo of a subject, and the later stop gives it up if it still keeps at least two */
 if(first0&&first0.phPins){const cf=CARD[first0.title],out=[],seen=new Set;first0.phPins.forEach(q=>{const k=key(q);if(seen.has(k)||(cf&&PIN[q.label]===cf)||out.length>=first)return;const St=owner.get(k);
   if(St){const n=St.phPins.findIndex(x=>key(x)===k);if(St.phPins.length<=2)return;if(n>=0)St.phPins.splice(n,1)}seen.add(k);out.push(q)});first0.phPins=out}
 later.forEach(St=>{if(St.phPins.length>cap)St.phPins=St.phPins.slice(0,cap)});
}catch(e){console.error(e)}};
